// Generated by Dartform. The dashboard template: it reads config.js
// (window.DASHBOARD), loads each table's rows from the backend's read-only
// dashboard routes, and draws the overview and one page per table. No
// libraries; charts are drawn as SVG.
//
// config.js looks like:
//   window.DASHBOARD = {
//     appName, accent, logo, backendUrl,
//     api: "serverpod" | "rest",
//     sections: [{ table, label, icon, fields: [{ name, label, type,
//       inTable, stat }] }],
//   };
// type is one of text, number, date, badge, relation, count.

(() => {
  'use strict';

  const C = window.DASHBOARD || { sections: [] };
  const sections = C.sections || [];
  const base = String(C.backendUrl || '').replace(/\/+$/, '');
  const keyName = 'dartform-dashboard-key:' + (C.appName || 'dashboard');
  const root = document.getElementById('app');

  // ---------- Small helpers ----------
  const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const nf = new Intl.NumberFormat();
  const num = (v) => (typeof v === 'number' ? v : Number(v));
  const isNum = (v) => v !== null && v !== '' && Number.isFinite(num(v));
  const fmtNum = (v) => (isNum(v) ? nf.format(Math.round(num(v) * 100) / 100) : '—');
  const compact = (v) => {
    const n = num(v), a = Math.abs(n);
    if (!Number.isFinite(n)) return '—';
    if (a >= 1e9) return (n / 1e9).toFixed(1) + 'B';
    if (a >= 1e6) return (n / 1e6).toFixed(1) + 'M';
    if (a >= 1e4) return Math.round(n / 1e3) + 'k';
    return fmtNum(n);
  };
  const toDate = (v) => {
    if (v instanceof Date) return v;
    if (v === null || v === undefined || v === '') return null;
    const d = new Date(v);
    return Number.isNaN(d.getTime()) ? null : d;
  };
  const day = (d) => (d ? d.toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric' }) : '—');
  const shortDay = (d) => d.toLocaleDateString(undefined, { day: 'numeric', month: 'short' });
  const now = new Date();
  const daysAgo = (n) => new Date(now.getTime() - n * 864e5);
  const css = (name) => getComputedStyle(document.documentElement).getPropertyValue(name).trim();
  const store = {
    get() { try { return localStorage.getItem(keyName) || ''; } catch (_) { return ''; } },
    set(v) { try { localStorage.setItem(keyName, v); } catch (_) { /* private mode */ } },
    clear() { try { localStorage.removeItem(keyName); } catch (_) { /* private mode */ } },
  };
  const snake = (s) => s.replace(/[A-Z]/g, (m) => '_' + m.toLowerCase());
  const value = (row, f) => {
    for (const k of [f.name, f.name + 'Id', snake(f.name), snake(f.name) + '_id']) {
      if (Object.prototype.hasOwnProperty.call(row, k)) return row[k];
    }
    return undefined;
  };

  if (C.accent) document.documentElement.style.setProperty('--accent', C.accent);
  document.title = (C.appName || 'Dashboard') + ' dashboard';

  // ---------- Icons (Tabler, MIT) ----------
  const icon = (d, size = 20) => `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${d}</svg>`;
  const I = {
    overview: '<path d="M4 4h6v8h-6z"/><path d="M4 16h6v4h-6z"/><path d="M14 12h6v8h-6z"/><path d="M14 4h6v4h-6z"/>',
    table: '<path d="M3 5a2 2 0 0 1 2 -2h14a2 2 0 0 1 2 2v14a2 2 0 0 1 -2 2h-14a2 2 0 0 1 -2 -2z"/><path d="M3 10h18"/><path d="M10 3v18"/>',
    rows: '<path d="M4 6h16"/><path d="M4 12h16"/><path d="M4 18h12"/>',
    plus: '<path d="M12 5l0 14"/><path d="M5 12l14 0"/>',
    sum: '<path d="M18 16v2a1 1 0 0 1 -1 1h-11l6 -7l-6 -7h11a1 1 0 0 1 1 1v2"/>',
    avg: '<path d="M3 17l6 -6l4 4l8 -8"/>',
    up: '<path d="M3 17l6 -6l4 4l8 -8"/><path d="M14 7l7 0l0 7"/>',
    down: '<path d="M3 7l6 6l4 -4l8 8"/><path d="M21 10l0 7l-7 0"/>',
    download: '<path d="M4 17v2a2 2 0 0 0 2 2h12a2 2 0 0 0 2 -2v-2"/><path d="M7 11l5 5l5 -5"/><path d="M12 4l0 12"/>',
    search: '<path d="M10 10m-7 0a7 7 0 1 0 14 0a7 7 0 1 0 -14 0"/><path d="M21 21l-6 -6"/>',
    refresh: '<path d="M20 11a8.1 8.1 0 0 0 -15.5 -2m-.5 -4v4h4"/><path d="M4 13a8.1 8.1 0 0 0 15.5 2m.5 4v-4h-4"/>',
    lock: '<path d="M5 13a2 2 0 0 1 2 -2h10a2 2 0 0 1 2 2v6a2 2 0 0 1 -2 2h-10a2 2 0 0 1 -2 -2z"/><path d="M8 11v-4a4 4 0 1 1 8 0v4"/>',
    left: '<path d="M15 6l-6 6l6 6"/>', right: '<path d="M9 6l6 6l-6 6"/>', x: '<path d="M18 6l-12 12"/><path d="M6 6l12 12"/>',
    sort: '<path d="M8 9l4 -4l4 4"/><path d="M16 15l-4 4l-4 -4"/>',
  };

  // ---------- Data ----------
  class LoadError extends Error {
    constructor(kind, message) { super(message); this.kind = kind; }
  }

  async function fetchRows(table, key) {
    let res;
    try {
      res = C.api === 'serverpod'
        ? await fetch(base + '/dashboard', {
            method: 'POST',
            headers: { 'content-type': 'application/json' },
            body: JSON.stringify({ method: 'rows', key, table }),
          })
        : await fetch(base + '/dashboard/' + encodeURIComponent(table), {
            headers: key ? { authorization: 'Bearer ' + key } : {},
          });
    } catch (_) {
      throw new LoadError('network', "Couldn't reach " + (base || 'the backend') + '.');
    }
    let body = null;
    try { body = await res.json(); } catch (_) { /* not JSON */ }
    // Serverpod returns the endpoint's JSON as a string.
    if (typeof body === 'string') { try { body = JSON.parse(body); } catch (_) { body = null; } }
    const error = body && body.error;
    if (res.status === 401 || (error && /dashboard key/i.test(error))) throw new LoadError('key', error || 'Missing or wrong dashboard key.');
    // The server is up but has no dashboard routes: it hasn't been
    // redeployed since the dashboard was generated.
    if (res.status === 404 && !error) {
      throw new LoadError('server', "Your backend doesn't have the dashboard yet. Redeploy it after generating, then try again.");
    }
    if (error || !res.ok || !body || !Array.isArray(body.rows)) {
      throw new LoadError('server', error || `The backend answered ${res.status}.`);
    }
    return { rows: body.rows, more: !!body.more };
  }

  const data = {}; // table -> { rows, more }
  let loadedAt = null;

  async function loadAll(key) {
    const results = await Promise.all(sections.map((s) => fetchRows(s.table, key).then(
      (r) => ({ s, r }), (e) => ({ s, e }))));
    const keyError = results.find((x) => x.e && x.e.kind === 'key');
    if (keyError) throw keyError.e;
    const failed = results.find((x) => x.e);
    if (failed && results.every((x) => x.e)) throw failed.e;
    for (const { s, r, e } of results) {
      // The backend was generated before this table was on the dashboard.
      const error = e && (/not a dashboard table/i.test(e.message)
        ? `Your backend doesn't serve ${s.label} to the dashboard yet. Redeploy it after generating, then refresh.`
        : e.message);
      data[s.table] = r || { rows: [], more: false, error };
    }
    loadedAt = new Date();
  }

  // ---------- Field roles ----------
  const fieldsOf = (s) => s.fields || [];
  const dateField = (s) => fieldsOf(s).find((f) => f.type === 'date');
  const titleField = (s) => fieldsOf(s).find((f) => f.type === 'text' && !/id$/i.test(f.name)) || fieldsOf(s).find((f) => f.type === 'text');
  const statFields = (s) => fieldsOf(s).filter((f) => f.stat && (f.type === 'number' || f.type === 'count'));
  function categoryField(s, rows) {
    const candidates = fieldsOf(s).filter((f) => f.type === 'badge').concat(fieldsOf(s).filter((f) => f.type === 'text'));
    for (const f of candidates) {
      const values = new Set(rows.map((r) => String(value(r, f))));
      if (values.size >= 2 && values.size <= 8 && rows.length >= values.size * 2) return f;
    }
    return null;
  }
  /// The section a relation field points to: the one whose table is the
  /// field's name, e.g. `company` or `companyId` -> table `company`.
  const relationTarget = (f) => {
    if (f.type !== 'relation') return null;
    const name = snake(f.name).replace(/_id$/, '');
    return sections.find((x) => x.table === name || x.table === name + 's') || null;
  };
  const relationLabel = (f, v) => {
    const target = relationTarget(f);
    if (!target || !data[target.table]) return null;
    const row = data[target.table].rows.find((r) => String(r.id) === String(v));
    return row ? rowTitle(target, row) : null;
  };
  const rowTitle = (s, r) => {
    const f = titleField(s);
    const v = f ? value(r, f) : undefined;
    return v === undefined || v === null || v === '' ? '#' + (r.id ?? '') : String(v);
  };

  // ---------- Rendering of values ----------
  const toneClasses = ['t-accent', 't-warning', 't-success', 't-slate', 't-violet', 't-danger'];
  const toneOf = (f, v, s) => {
    const list = [...new Set((data[s.table]?.rows || []).map((r) => String(value(r, f))))].sort();
    return toneClasses[Math.max(0, list.indexOf(String(v))) % toneClasses.length];
  };
  function cell(f, v, s) {
    if (v === undefined || v === null || v === '') return '<span class="muted">—</span>';
    switch (f.type) {
      case 'number': case 'count': return esc(fmtNum(v));
      case 'date': return esc(day(toDate(v)));
      case 'badge':
        if (typeof v === 'boolean') return v ? '<span class="pill t-success">Yes</span>' : '<span class="pill t-slate">No</span>';
        return `<span class="pill ${toneOf(f, v, s)}">${esc(v)}</span>`;
      case 'relation': {
        const label = relationLabel(f, v);
        return `<span class="rel">${esc(label ?? v)}</span>`;
      }
      default: return esc(typeof v === 'object' ? JSON.stringify(v) : v);
    }
  }

  // ---------- Charts ----------
  let gid = 0;
  function sparkline(values, color) {
    if (values.length < 2 || values.every((v) => v === values[0])) values = values.length < 2 ? [0, values[0] || 0] : values;
    const w = 76, h = 42, max = Math.max(...values), min = Math.min(...values), span = max - min || 1;
    const pts = values.map((v, i) => [w * i / (values.length - 1), h - 4 - (v - min) / span * (h - 8)]);
    let d = `M${pts[0][0]},${pts[0][1]}`;
    for (let i = 1; i < pts.length; i++) { const mx = (pts[i - 1][0] + pts[i][0]) / 2; d += ` C${mx},${pts[i - 1][1]} ${mx},${pts[i][1]} ${pts[i][0]},${pts[i][1]}`; }
    const id = 'sg' + (++gid), end = pts[pts.length - 1];
    return `<svg class="spark" viewBox="0 0 ${w} ${h}" aria-hidden="true"><defs><linearGradient id="${id}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${color}" stop-opacity=".22"/><stop offset="1" stop-color="${color}" stop-opacity="0"/></linearGradient></defs>
      <path d="${d} L${w},${h} L0,${h} Z" fill="url(#${id})"/><path d="${d}" fill="none" stroke="${color}" stroke-width="2.2" stroke-linecap="round"/><circle cx="${end[0]}" cy="${end[1]}" r="3.5" fill="${color}"/></svg>`;
  }

  function donut(values, colors) {
    const total = values.reduce((a, b) => a + b, 0) || 1, r = 70, c = 2 * Math.PI * r;
    let off = 0;
    const arcs = values.map((v, i) => {
      const len = v / total * c, gap = values.filter((x) => x > 0).length > 1 ? 4 : 0;
      const s = `<circle r="${r}" cx="95" cy="95" fill="none" stroke="${colors[i % colors.length]}" stroke-width="22" stroke-dasharray="${Math.max(len - gap, 0)} ${c}" stroke-dashoffset="${-off}"/>`;
      off += len; return s;
    }).join('');
    return `<svg viewBox="0 0 190 190" width="100%" height="100%" aria-hidden="true"><circle r="${r}" cx="95" cy="95" fill="none" stroke="${css('--bg')}" stroke-width="22"/><g transform="rotate(-90 95 95)">${arcs}</g></svg>`;
  }

  function lineChart(el, labels, values, color, unit) {
    const W = Math.max(el.clientWidth || 600, 280), H = 250, pl = 40, pr = 16, pt = 12, pb = 28;
    const max = Math.max(...values, 1) * 1.15;
    const x = (i) => pl + (W - pl - pr) * i / Math.max(labels.length - 1, 1);
    const y = (v) => pt + (H - pt - pb) * (1 - v / max);
    const path = values.map((v, i) => `${i ? 'L' : 'M'}${x(i)},${y(v)}`).join(' ');
    let grid = '';
    for (let g = 0; g <= 4; g++) {
      const yy = pt + (H - pt - pb) * g / 4;
      grid += `<line x1="${pl}" x2="${W - pr}" y1="${yy}" y2="${yy}" stroke="${css('--border')}" stroke-dasharray="3 4"/>`;
      grid += `<text x="${pl - 8}" y="${yy + 4}" text-anchor="end" font-size="11" fill="${css('--muted')}">${compact(Math.round(max * (1 - g / 4)))}</text>`;
    }
    const step = Math.ceil(labels.length / 6);
    const xl = labels.map((l, i) => (i % step === 0 || i === labels.length - 1) ? `<text x="${x(i)}" y="${H - 8}" text-anchor="middle" font-size="11" fill="${css('--muted')}">${esc(l)}</text>` : '').join('');
    const id = 'lg' + (++gid);
    el.innerHTML = `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(unit)} per week">
      <defs><linearGradient id="${id}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${color}" stop-opacity=".18"/><stop offset="1" stop-color="${color}" stop-opacity="0"/></linearGradient></defs>
      ${grid}${xl}
      <path d="${path} L${x(values.length - 1)},${H - pb} L${x(0)},${H - pb} Z" fill="url(#${id})"/>
      <path d="${path}" fill="none" stroke="${color}" stroke-width="2.6" stroke-linejoin="round"/>
      <line class="guide" y1="${pt}" y2="${H - pb}" stroke="${css('--border')}" opacity="0"/>
      <circle class="dot" r="5" fill="${color}" stroke="#fff" stroke-width="2" opacity="0"/>
      <circle cx="${x(values.length - 1)}" cy="${y(values[values.length - 1])}" r="4" fill="${color}"/>
    </svg><div class="tip"></div>`;
    const svg = el.querySelector('svg'), tip = el.querySelector('.tip');
    const guide = svg.querySelector('.guide'), dot = svg.querySelector('.dot');
    svg.addEventListener('pointermove', (e) => {
      const r = svg.getBoundingClientRect(), px = (e.clientX - r.left) * W / r.width;
      const i = Math.max(0, Math.min(labels.length - 1, Math.round((px - pl) / (W - pl - pr) * (labels.length - 1))));
      guide.setAttribute('x1', x(i)); guide.setAttribute('x2', x(i)); guide.setAttribute('opacity', 1);
      dot.setAttribute('cx', x(i)); dot.setAttribute('cy', y(values[i])); dot.setAttribute('opacity', 1);
      tip.innerHTML = `Week of ${esc(labels[i])}<br><b>${fmtNum(values[i])}</b> ${esc(unit)}`;
      tip.style.left = (x(i) / W * 100) + '%'; tip.style.top = (y(values[i]) / H * 100) + '%'; tip.style.opacity = 1;
    });
    svg.addEventListener('pointerleave', () => { guide.setAttribute('opacity', 0); dot.setAttribute('opacity', 0); tip.style.opacity = 0; });
  }

  // ---------- Derived numbers ----------
  const WEEKS = 12;
  const weekLabels = Array.from({ length: WEEKS }, (_, i) => shortDay(daysAgo((WEEKS - 1 - i) * 7 + 6)));
  function perWeek(rows, f) {
    const out = new Array(WEEKS).fill(0);
    for (const r of rows) {
      const d = toDate(value(r, f));
      if (!d) continue;
      const age = Math.floor((now - d) / (7 * 864e5));
      if (age >= 0 && age < WEEKS) out[WEEKS - 1 - age] += 1;
    }
    return out;
  }
  const cumulative = (rows, f) => {
    const dates = rows.map((r) => toDate(value(r, f))).filter(Boolean);
    return Array.from({ length: 8 }, (_, i) => dates.filter((d) => d <= daysAgo((7 - i) * 7)).length);
  };
  const within = (rows, f, from, to) => rows.filter((r) => { const d = toDate(value(r, f)); return d && d > daysAgo(from) && d <= daysAgo(to); }).length;
  const pct = (a, b) => (b === 0 ? null : (a - b) / b * 100);
  const palette = () => [css('--accent'), css('--accent-2'), css('--success'), css('--slate'), css('--violet'), '#f28c6b', css('--danger'), '#0f9f8f'];

  const tileGrid = (tiles) => `<div class="grid-4" style="grid-template-columns:repeat(${Math.max(1, Math.min(tiles.length, 4))}, minmax(0, 1fr))">${tiles.join('')}</div>`;

  /// "Companies with the most employees": the first relation from one
  /// section to another, ranked by how many rows point at each target row.
  function topLinkedCard() {
    for (const s of sections) {
      for (const f of fieldsOf(s)) {
        const target = relationTarget(f);
        if (!target || target === s) continue;
        const counts = new Map();
        for (const r of data[s.table].rows) {
          const v = value(r, f);
          if (v !== undefined && v !== null) counts.set(String(v), (counts.get(String(v)) || 0) + 1);
        }
        if (!counts.size) continue;
        const top = [...counts.entries()].sort((a, b) => b[1] - a[1]).slice(0, 5);
        return `<div class="card"><div class="card-head"><h3>${esc(target.label)} with the most ${esc(s.label.toLowerCase())}</h3><button class="link" data-go="${esc(target.table)}">View all</button></div>
          <div class="ranked">${top.map(([id, n], i) => {
            const row = data[target.table].rows.find((r) => String(r.id) === id);
            const title = row ? rowTitle(target, row) : '#' + id;
            return `<button class="item" data-table="${esc(target.table)}" data-ref="${esc(JSON.stringify(row ? row.id ?? null : null))}"><span class="rank">${i + 1}</span><span class="avatar">${esc(title.slice(0, 2).toUpperCase())}</span>
              <span class="meta"><b>${esc(title)}</b><span>${fmtNum(n)} ${esc(s.label.toLowerCase())}</span></span><span class="val">${fmtNum(n)}</span></button>`;
          }).join('')}</div></div>`;
      }
    }
    return '';
  }

  const bottomRow = (cards) => {
    const shown = cards.filter(Boolean).slice(0, 2);
    return shown.length ? `<div class="${shown.length > 1 ? 'grid-2' : ''}">${shown.join('')}</div>` : '';
  };

  function kpi(label, val, change, iconPath, tone, spark, note) {
    const up = (change ?? 0) >= 0, col = css(up ? '--success' : '--danger');
    return `<div class="card"><div class="kpi-top"><div class="kpi-icon" style="background:color-mix(in srgb, ${tone} 12%, white);color:${tone}">${icon(iconPath, 22)}</div><div class="kpi-label" title="${esc(label)}">${esc(label)}</div></div>
      <div class="kpi-bottom"><div style="min-width:0"><div class="kpi-value">${esc(val)}</div>
      ${change == null ? `<div class="delta">${esc(note || ' ')}</div>` : `<div class="delta ${up ? 'up' : 'down'}">${icon(up ? I.up : I.down, 16)}<b>${Math.abs(change).toFixed(1)}%</b> ${esc(note || 'vs previous 30 days')}</div>`}</div>
      ${spark ? sparkline(spark, col) : ''}</div></div>`;
  }

  const initials = () => (C.appName || 'D').split(/\s+/).filter(Boolean).map((w) => w[0]).join('').slice(0, 2).toUpperCase();

  // ---------- State and shell ----------
  const state = { view: 'overview', query: '', filter: null, page: 1, sort: null, key: store.get() };
  const PER_PAGE = 10;

  function shell() {
    root.className = 'app';
    root.innerHTML = `
      <aside class="sidebar">
        <div class="brand"><div class="mark">${C.logo ? `<img src="${esc(C.logo)}" alt="">` : esc(initials())}</div>
          <div><div class="brand-name">${esc(C.appName || 'Dashboard')}</div><div class="brand-sub">Dashboard</div></div></div>
        <nav aria-label="Sections">
          <button class="nav-tile" data-view="overview">${icon(I.overview, 21)}<span class="label">Overview</span></button>
          <div class="nav-label">DATA</div>
          ${sections.map((s) => `<button class="nav-tile" data-view="${esc(s.table)}">${s.icon ? `<span class="emoji">${esc(s.icon)}</span>` : icon(I.table, 21)}<span class="label">${esc(s.label)}</span><span class="count">${compact((data[s.table]?.rows || []).length)}${data[s.table]?.more ? '+' : ''}</span></button>`).join('')}
        </nav>
        <div class="glance"><h4>At a glance</h4>${sections.slice(0, 4).map((s) => `<div class="row"><span>${esc(s.label)}</span><b>${compact((data[s.table]?.rows || []).length)}${data[s.table]?.more ? '+' : ''}</b></div>`).join('')}</div>
      </aside>
      <div class="main">
        <header class="topbar"><h1 id="top-title"></h1><div class="spacer"></div>
          <span class="updated">${loadedAt ? 'Updated ' + loadedAt.toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit' }) : ''}</span>
          <button class="icon-btn" id="refresh" title="Refresh" aria-label="Refresh">${icon(I.refresh)}</button>
          ${state.key ? `<button class="icon-btn" id="forget" title="Forget the dashboard key on this device" aria-label="Forget the dashboard key">${icon(I.lock)}</button>` : ''}
        </header>
        <div class="content" id="content"></div>
      </div>
      <div class="scrim" id="scrim"></div>
      <aside class="drawer" id="drawer" aria-label="Row details"></aside>`;
    root.querySelectorAll('.nav-tile').forEach((b) => b.addEventListener('click', () => go(b.dataset.view)));
    root.querySelector('#refresh').addEventListener('click', () => start());
    root.querySelector('#forget')?.addEventListener('click', () => { store.clear(); state.key = ''; start(); });
    root.querySelector('#scrim').addEventListener('click', closeDrawer);
    root.querySelector('#content').addEventListener('click', onContentClick);
  }

  function go(view) {
    Object.assign(state, { view, query: '', filter: null, page: 1, sort: null });
    const hash = view === 'overview' ? '' : '#' + view;
    if (location.hash !== hash) history.replaceState(null, '', hash || location.pathname + location.search);
    render();
  }
  const viewFromHash = () => {
    const name = decodeURIComponent(location.hash.replace(/^#/, ''));
    return sections.some((x) => x.table === name) ? name : 'overview';
  };
  window.addEventListener('hashchange', () => { if (root.querySelector('#content')) go(viewFromHash()); });

  function render() {
    root.querySelectorAll('.nav-tile').forEach((b) => b.dataset.view === state.view ? b.setAttribute('aria-current', 'page') : b.removeAttribute('aria-current'));
    const s = sections.find((x) => x.table === state.view);
    root.querySelector('#top-title').textContent = s ? s.label : 'Overview';
    if (s) sectionView(s); else overview();
  }

  // ---------- Overview ----------
  function overview() {
    const el = root.querySelector('#content');
    const acc = css('--accent');
    const hour = now.getHours();
    const greeting = hour < 12 ? 'Good morning' : hour < 18 ? 'Good afternoon' : 'Good evening';
    const tones = [acc, css('--success'), css('--slate'), css('--accent-2')];
    const tiles = sections.slice(0, 4).map((s, i) => {
      const rows = data[s.table].rows, df = dateField(s);
      const recent = df ? within(rows, df, 30, 0) : null, before = df ? within(rows, df, 60, 30) : null;
      return kpi(s.label, compact(rows.length) + (data[s.table].more ? '+' : ''), df ? pct(recent, before) : null, I.rows, tones[i % 4],
        df ? cumulative(rows, df) : null, df ? `${fmtNum(recent)} added in 30 days` : 'rows');
    });
    const trendSection = sections.find((s) => dateField(s) && data[s.table].rows.length);
    const catSection = sections.find((s) => categoryField(s, data[s.table].rows));
    const latestSection = trendSection;
    const colors = palette();

    let trendCard;
    if (trendSection) {
      const df = dateField(trendSection), weekly = perWeek(data[trendSection.table].rows, df);
      const busiest = weekly.indexOf(Math.max(...weekly));
      trendCard = `<div class="card"><div class="card-head"><h3>${esc(trendSection.label)} added per week</h3><button class="link" data-go="${esc(trendSection.table)}">Open ${esc(trendSection.label)}</button></div>
        <div class="legend"><span><i style="background:${acc}"></i>Added, by ${esc(df.label)}</span></div>
        <div class="chart-wrap" id="trend"></div>
        <div class="minis"><div class="mini"><span>Total</span><b>${compact(data[trendSection.table].rows.length)}</b></div>
          <div class="mini"><span>Last 12 weeks</span><b>${fmtNum(weekly.reduce((a, b) => a + b, 0))}</b></div>
          <div class="mini"><span>Busiest week</span><b>${weekly[busiest] ? esc(weekLabels[busiest]) : '—'}</b></div>
          <div class="mini"><span>This week</span><b>${fmtNum(weekly[WEEKS - 1])}</b></div></div></div>`;
    } else {
      const max = Math.max(...sections.map((s) => data[s.table].rows.length), 1);
      trendCard = `<div class="card"><div class="card-head"><h3>Rows per table</h3></div><div class="rows" style="margin-top:0">${sections.map((s) => {
        const n = data[s.table].rows.length;
        return `<div class="row-line"><span class="name" style="width:160px">${esc(s.label)}</span><span class="bar"><i style="width:${n / max * 100}%"></i></span><span class="p">${compact(n)}</span></div>`;
      }).join('')}</div></div>`;
    }

    let catCard = '';
    if (catSection) {
      const rows = data[catSection.table].rows, f = categoryField(catSection, rows);
      const counts = new Map();
      for (const r of rows) { const k = String(value(r, f) ?? '—'); counts.set(k, (counts.get(k) || 0) + 1); }
      const entries = [...counts.entries()].sort((a, b) => b[1] - a[1]);
      catCard = `<div class="card"><div class="card-head"><h3>${esc(catSection.label)} by ${esc(f.label)}</h3></div>
        <div class="donut-wrap">${donut(entries.map((e) => e[1]), colors)}<div class="center-label"><div><b>${compact(rows.length)}</b><span>${esc(catSection.label.toLowerCase())}</span></div></div></div>
        <div class="rows">${entries.map(([k, n], i) => `<div class="row-line"><i class="sw" style="background:${colors[i % colors.length]}"></i><span class="name">${esc(k === 'true' ? 'Yes' : k === 'false' ? 'No' : k)}</span><span class="n">${fmtNum(n)}</span><span class="p">${(n / rows.length * 100).toFixed(1)}%</span></div>`).join('')}</div></div>`;
    }

    let latestCard = '';
    if (latestSection) {
      const df = dateField(latestSection);
      const latest = data[latestSection.table].rows.filter((r) => toDate(value(r, df))).sort((a, b) => toDate(value(b, df)) - toDate(value(a, df))).slice(0, 5);
      latestCard = `<div class="card"><div class="card-head"><h3>Latest ${esc(latestSection.label.toLowerCase())}</h3><button class="link" data-go="${esc(latestSection.table)}">View all</button></div>
        <div class="ranked">${latest.map((r, i) => `<button class="item" data-row="${i}" data-table="${esc(latestSection.table)}" data-ref="${esc(JSON.stringify(r.id ?? null))}"><span class="rank">${i + 1}</span><span class="avatar">${esc(rowTitle(latestSection, r).slice(0, 2).toUpperCase())}</span>
          <span class="meta"><b>${esc(rowTitle(latestSection, r))}</b><span>${esc(df.label)}: ${esc(day(toDate(value(r, df))))}</span></span></button>`).join('') || '<div class="muted">Nothing yet.</div>'}</div></div>`;
    }
    const linkedCard = topLinkedCard();
    const tablesCard = `<div class="card"><div class="card-head"><h3>Your data</h3></div><div class="rows" style="margin-top:0">${sections.map((s) => `<div class="row-line"><button class="link" data-go="${esc(s.table)}">${esc(s.label)}</button><span class="n">${compact(data[s.table].rows.length)}${data[s.table].more ? '+' : ''} rows</span></div>${data[s.table].error ? `<div class="note">${esc(s.label)}: ${esc(data[s.table].error)}</div>` : ''}`).join('')}</div></div>`;

    el.innerHTML = `
      <div class="page-head"><div><h2>${greeting} 👋</h2><p>Here's what's in ${esc(C.appName || 'your app')}'s data, ${esc(day(now))}.</p></div></div>
      ${sections.length ? `${tileGrid(tiles)}
      <div class="${catCard ? 'grid-53' : ''}">${trendCard}${catCard}</div>
      ${bottomRow([latestCard, linkedCard, trendSection ? tablesCard : ''])}` : '<div class="card empty"><b>No tables on this dashboard</b>Choose some in Dartform\'s Dashboard Generator and generate again.</div>'}`;
    if (trendSection) {
      requestAnimationFrame(() => lineChart(document.getElementById('trend'), weekLabels, perWeek(data[trendSection.table].rows, dateField(trendSection)), acc, trendSection.label.toLowerCase()));
    }
  }

  // ---------- One table ----------
  function sectionView(s) {
    const el = root.querySelector('#content');
    const acc = css('--accent');
    const all = data[s.table].rows;
    const df = dateField(s), cat = categoryField(s, all);
    const cols = fieldsOf(s).filter((f) => f.inTable !== false);

    const tiles = [kpi('Total ' + s.label.toLowerCase(), compact(all.length) + (data[s.table].more ? '+' : ''), null, I.rows, acc, df ? cumulative(all, df) : null, 'rows')];
    if (df) {
      const recent = within(all, df, 30, 0), before = within(all, df, 60, 30);
      tiles.push(kpi('Added in 30 days', fmtNum(recent), pct(recent, before), I.plus, css('--success'), perWeek(all, df).slice(-8)));
    }
    for (const f of fieldsOf(s)) {
      const target = relationTarget(f);
      if (!target || tiles.length >= 4) continue;
      const linked = new Set(all.map((r) => value(r, f)).filter((v) => v !== undefined && v !== null).map(String));
      tiles.push(kpi(target.label + ' linked', fmtNum(linked.size), null, I.table, css('--accent-2'), null,
        `of ${fmtNum(data[target.table]?.rows.length ?? 0)} ${target.label.toLowerCase()}`));
    }
    for (const f of statFields(s)) {
      if (tiles.length >= 4) break;
      const vals = all.map((r) => value(r, f)).filter(isNum).map(num);
      const sum = vals.reduce((a, b) => a + b, 0);
      tiles.push(kpi('Total ' + f.label.toLowerCase(), compact(sum), null, I.sum, css('--slate'), null, vals.length ? `${fmtNum(vals.length)} rows` : 'no values yet'));
      if (tiles.length < 4) tiles.push(kpi('Average ' + f.label.toLowerCase(), vals.length ? fmtNum(sum / vals.length) : '—', null, I.avg, css('--accent-2'), null, 'per row'));
    }

    let rows = all.slice();
    const q = state.query.trim().toLowerCase();
    if (q) rows = rows.filter((r) => fieldsOf(s).some((f) => String(value(r, f) ?? '').toLowerCase().includes(q)));
    if (cat && state.filter !== null) rows = rows.filter((r) => String(value(r, cat)) === state.filter);
    const sort = state.sort || (df ? { name: df.name, dir: -1 } : null);
    if (sort) {
      const f = fieldsOf(s).find((x) => x.name === sort.name) || { name: sort.name };
      rows.sort((a, b) => {
        let x = value(a, f), y = value(b, f);
        if (f.type === 'date') { x = toDate(x)?.getTime() ?? -Infinity; y = toDate(y)?.getTime() ?? -Infinity; }
        else if (isNum(x) && isNum(y)) { x = num(x); y = num(y); }
        else { x = String(x ?? ''); y = String(y ?? ''); }
        return (x > y ? 1 : x < y ? -1 : 0) * sort.dir;
      });
    }
    const pages = Math.max(1, Math.ceil(rows.length / PER_PAGE));
    state.page = Math.min(state.page, pages);
    const shown = rows.slice((state.page - 1) * PER_PAGE, state.page * PER_PAGE);
    state.shown = shown;

    const catValues = cat ? [...new Set(all.map((r) => String(value(r, cat))))].sort() : [];
    el.innerHTML = `
      <div class="page-head"><div><h2>${esc(s.label)}</h2><p>${fmtNum(all.length)}${data[s.table].more ? '+' : ''} rows · read-only</p></div>
        <div class="actions"><button class="btn" data-csv="1">${icon(I.download, 18)} Download CSV</button></div></div>
      ${data[s.table].more ? `<div class="note">Showing the first ${fmtNum(all.length)} rows. Totals and charts cover those rows.</div>` : ''}
      ${data[s.table].error ? `<div class="note">${esc(data[s.table].error)}</div>` : ''}
      ${tileGrid(tiles)}
      ${df && all.length ? `<div class="${cat ? 'grid-53' : ''}"><div class="card"><div class="card-head"><h3>Added per week</h3></div><div class="chart-wrap" id="trend"></div></div>${cat ? categoryCard(s, all, cat) : ''}</div>` : (cat ? `<div class="grid-2">${categoryCard(s, all, cat)}</div>` : '')}
      <div class="toolbar">
        <label class="search">${icon(I.search, 18)}<input id="q" type="search" placeholder="Search ${esc(s.label.toLowerCase())}" value="${esc(state.query)}" aria-label="Search"></label>
        ${catValues.map((v) => `<button class="chip" data-filter="${esc(v)}" aria-pressed="${state.filter === v}">${esc(v === 'true' ? 'Yes' : v === 'false' ? 'No' : v)}</button>`).join('')}
      </div>
      <div class="card table-card"><div class="table-scroll"><table>
        <thead><tr>${cols.map((f) => `<th class="${f.type === 'number' || f.type === 'count' ? 'end' : ''}"><button data-sort="${esc(f.name)}">${esc(f.label)}${sort && sort.name === f.name ? icon(I.sort, 13) : ''}</button></th>`).join('')}</tr></thead>
        <tbody>${shown.map((r, i) => `<tr data-row="${i}">${cols.map((f) => `<td class="${f.type === 'number' || f.type === 'count' ? 'end' : ''}${f === titleField(s) ? ' strong' : ''}">${cell(f, value(r, f), s)}</td>`).join('')}</tr>`).join('') ||
          `<tr><td colspan="${cols.length || 1}" class="empty"><b>${all.length ? 'No rows match' : 'No ' + esc(s.label.toLowerCase()) + ' yet'}</b>${all.length ? 'Try another search.' : 'They appear here once your app adds some.'}</td></tr>`}</tbody>
      </table></div>
      <div class="table-foot"><span>${rows.length ? `${(state.page - 1) * PER_PAGE + 1}–${(state.page - 1) * PER_PAGE + shown.length} of ${fmtNum(rows.length)}` : 'No results'}</span><span class="spacer"></span>
        <button data-page="-1" aria-label="Previous page" ${state.page <= 1 ? 'disabled' : ''}>${icon(I.left)}</button><span>${state.page} / ${pages}</span>
        <button data-page="1" aria-label="Next page" ${state.page >= pages ? 'disabled' : ''}>${icon(I.right)}</button></div></div>`;
    const qi = el.querySelector('#q');
    qi.addEventListener('input', () => { state.query = qi.value; state.page = 1; sectionView(s); const n = root.querySelector('#q'); n.focus(); n.setSelectionRange(n.value.length, n.value.length); });
    if (df && all.length) requestAnimationFrame(() => lineChart(document.getElementById('trend'), weekLabels, perWeek(all, df), acc, s.label.toLowerCase()));
  }

  function categoryCard(s, rows, f) {
    const colors = palette(), counts = new Map();
    for (const r of rows) { const k = String(value(r, f) ?? '—'); counts.set(k, (counts.get(k) || 0) + 1); }
    const entries = [...counts.entries()].sort((a, b) => b[1] - a[1]);
    return `<div class="card"><div class="card-head"><h3>By ${esc(f.label.toLowerCase())}</h3></div>
      <div class="donut-wrap">${donut(entries.map((e) => e[1]), colors)}<div class="center-label"><div><b>${compact(rows.length)}</b><span>rows</span></div></div></div>
      <div class="rows">${entries.map(([k, n], i) => `<div class="row-line"><i class="sw" style="background:${colors[i % colors.length]}"></i><span class="name">${esc(k === 'true' ? 'Yes' : k === 'false' ? 'No' : k)}</span><span class="n">${fmtNum(n)}</span><span class="p">${(n / rows.length * 100).toFixed(1)}%</span></div>`).join('')}</div></div>`;
  }

  function onContentClick(e) {
    const t = e.target.closest('button, tr[data-row]');
    if (!t) return;
    const s = sections.find((x) => x.table === state.view);
    if (t.dataset.go) go(t.dataset.go);
    else if (t.dataset.sort) { const n = t.dataset.sort; const cur = state.sort; state.sort = { name: n, dir: cur && cur.name === n ? -cur.dir : 1 }; sectionView(s); }
    else if (t.dataset.page) { state.page += Number(t.dataset.page); sectionView(s); }
    else if (t.dataset.filter !== undefined) { state.filter = state.filter === t.dataset.filter ? null : t.dataset.filter; state.page = 1; sectionView(s); }
    else if (t.dataset.csv) downloadCsv(s);
    else if (t.dataset.table) {
      const sec = sections.find((x) => x.table === t.dataset.table);
      const ref = JSON.parse(t.dataset.ref);
      const row = data[sec.table].rows.find((r) => (r.id ?? null) === ref);
      if (row) openDrawer(sec, row);
    } else if (t.dataset.row !== undefined && s) openDrawer(s, state.shown[Number(t.dataset.row)]);
  }

  function openDrawer(s, r) {
    const d = root.querySelector('#drawer');
    const known = new Set(fieldsOf(s).flatMap((f) => [f.name, f.name + 'Id', snake(f.name), snake(f.name) + '_id']));
    const extra = Object.keys(r).filter((k) => !known.has(k));
    d.innerHTML = `<div style="display:flex;align-items:center;gap:10px"><h2 style="flex:1">${esc(rowTitle(s, r))}</h2><button class="icon-btn" id="close" aria-label="Close">${icon(I.x)}</button></div>
      <div class="sub">${esc(s.label)}</div>
      <dl class="fields">${fieldsOf(s).map((f) => `<dt>${esc(f.label)}</dt><dd>${cell(f, value(r, f), s)}</dd>`).join('')}
        ${extra.map((k) => `<dt>${esc(k)}</dt><dd>${cell({ type: 'text' }, r[k], s)}</dd>`).join('')}</dl>`;
    d.classList.add('open'); root.querySelector('#scrim').classList.add('open');
    d.querySelector('#close').addEventListener('click', closeDrawer); d.querySelector('#close').focus();
  }
  function closeDrawer() { root.querySelector('#drawer')?.classList.remove('open'); root.querySelector('#scrim')?.classList.remove('open'); }

  function downloadCsv(s) {
    const cols = fieldsOf(s);
    const q = (v) => { const t = v === undefined || v === null ? '' : typeof v === 'object' ? JSON.stringify(v) : String(v); return /[",\n]/.test(t) ? '"' + t.replace(/"/g, '""') + '"' : t; };
    const lines = [cols.map((f) => q(f.label)).join(','), ...data[s.table].rows.map((r) => cols.map((f) => q(value(r, f))).join(','))];
    const blob = new Blob([lines.join('\n')], { type: 'text/csv' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob); a.download = s.table + '.csv';
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(a.href), 1000);
  }

  // ---------- Key screen, errors, start ----------
  function screen(inner) {
    root.className = '';
    root.innerHTML = `<div class="screen"><div class="card">${inner}</div></div>`;
  }

  function keyScreen(message) {
    screen(`<div class="mark">${C.logo ? `<img src="${esc(C.logo)}" alt="">` : esc(initials())}</div>
      <h2>${esc(C.appName || 'Dashboard')}</h2>
      <p>Enter the dashboard key you were given. It's kept on this device only.</p>
      <form id="key-form"><label for="key">Dashboard key</label>
        ${message ? `<div class="error">${esc(message)}</div>` : ''}
        <input id="key" type="password" autocomplete="off" required>
        <button class="btn primary" type="submit">Open dashboard</button></form>`);
    const input = root.querySelector('#key');
    input.focus();
    root.querySelector('#key-form').addEventListener('submit', (e) => {
      e.preventDefault();
      state.key = input.value.trim();
      start();
    });
  }

  function errorScreen(err) {
    screen(`<h2>The dashboard can't load</h2><p>${esc(err.message)}</p>
      <p>Backend: <code>${esc(base || 'not set')}</code></p>
      <button class="btn primary" id="retry">Try again</button>`);
    root.querySelector('#retry').addEventListener('click', () => start());
  }

  let loadedOnce = false;
  async function start() {
    if (!root.children.length) screen('<p>Loading…</p>');
    try {
      await loadAll(state.key);
    } catch (err) {
      if (err.kind === 'key') {
        const hadKey = !!state.key;
        store.clear(); state.key = '';
        return keyScreen(hadKey ? "That key didn't work. Check it and try again." : '');
      }
      return errorScreen(err);
    }
    if (state.key) store.set(state.key);
    if (!loadedOnce) { state.view = viewFromHash(); loadedOnce = true; }
    shell();
    render();
  }

  document.addEventListener('keydown', (e) => { if (e.key === 'Escape') closeDrawer(); });
  let resizeTimer;
  window.addEventListener('resize', () => { clearTimeout(resizeTimer); resizeTimer = setTimeout(() => { if (root.querySelector('#trend')) render(); }, 150); });
  start();
})();
